'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var max = require( '@stdlib/math/base/special/fast/max' );
var format = require( '@stdlib/string/format' );
var ndarray = require( './ndarray.js' );


// MAIN //

/**
* Generates a Cauchy matrix.
*
* @param {string} order - storage layout
* @param {NonNegativeInteger} M - number of indexed elements in `x`
* @param {NonNegativeInteger} N - number of indexed elements in `y`
* @param {Collection} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {Collection} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {Collection} out - output array
* @param {integer} LDO - stride length between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of `out`)
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} ninth argument must be a valid stride length
* @returns {Collection} output array
*
* @example
* var x = [ 3.0, 5.0 ];
* var y = [ 1.0, 4.0 ];
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gcauchyMatrix( 'row-major', x.length, y.length, x, 1, y, 1, out, 2 );
* // out => [ 0.5, -1.0, 0.25, 1.0 ]
*/
function gcauchyMatrix( order, M, N, x, strideX, y, strideY, out, LDO ) {
	var iscm;
	var sa1;
	var sa2;
	var ox;
	var oy;
	var k;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	iscm = isColumnMajor( order );
	if ( iscm ) {
		k = M;
	} else {
		k = N;
	}
	if ( LDO < max( 1, k ) ) {
		throw new RangeError( format( 'invalid argument. Ninth argument must be greater than or equal to max(1,%d). Value: `%d`.', k, LDO ) );
	}
	if ( M === 0 || N === 0 ) {
		return out;
	}
	ox = stride2offset( M, strideX );
	oy = stride2offset( N, strideY );
	if ( iscm ) {
		sa1 = 1;
		sa2 = LDO;
	} else { // order === 'row-major'
		sa1 = LDO;
		sa2 = 1;
	}
	return ndarray( M, N, x, strideX, ox, y, strideY, oy, out, sa1, sa2, 0 );
}


// EXPORTS //

module.exports = gcauchyMatrix;
